/* Chapter 1 original visual learning laboratory. Based on original Netzwerk A1.1 topics; independent materials, not publisher images. */
(()=>{'use strict';
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','\'':'&#39;'}[c]));
const words=[['Wasser','das Wasser','water','🥛'],['Rucksack','der Rucksack','backpack','🎒'],['Frühstück','das Frühstück','breakfast','🥐'],['Apfel','der Apfel','apple','🍎'],['Brot','das Brot','bread','🍞'],['Bahnhof','der Bahnhof','train station','🚉'],['Auto','das Auto','car','🚗'],['Buch','das Buch','book','📖']];
const places=[['Deutschland','Deutsch','DE'],['Österreich','Deutsch','AT'],['die Schweiz','Deutsch, Französisch, Italienisch','CH'],['Frankreich','Französisch','FR'],['Spanien','Spanisch','ES'],['Indien','Hindi, Englisch und andere Sprachen','IN']];
const scenes=[{label:'Meeting a classmate',tone:'Informal · du',left:'Hallo! Ich heiße Lina.',right:'Hallo Lina! Ich heiße Ben. Wie geht es dir?',end:'Danke, gut. Und dir?',art:'🎒',tip:'Use du and dir with a classmate.'},{label:'Meeting a teacher',tone:'Polite · Sie',left:'Guten Tag! Ich heiße Lina.',right:'Guten Tag, Lina. Ich bin Frau Weber.',end:'Wie geht es Ihnen? Danke, gut.',art:'📚',tip:'Use Sie and Ihnen to address the teacher politely.'},{label:'Saying goodbye',tone:'Situation matters',left:'Tschüss, Ben!',right:'Tschüss, Lina! Bis morgen!',end:'Auf Wiedersehen, Frau Weber!',art:'👋',tip:'Tschüss is informal; Auf Wiedersehen is polite.'}];
function render(){
return `<section class="ch1-gallery" id="chapter-1-visual-lab" aria-label="Visual discovery Chapter 1">
<header class="ch1-gallery-intro"><span class="eyebrow">Visual language lab · Chapter 1</span><h5>Look, listen, speak and explore</h5><p>Explore people, everyday objects, countries and contact details before practising the chapter conversations. These are original learning scenes inspired by the textbook's teaching methods.</p></header>
<div class="ch1-lab-area"><div class="ch1-lab-heading"><h6>1 · Conversations in context</h6><p>Watch how the greeting changes with the person and situation.</p></div><div class="ch1-scene-grid">${scenes.map((x,i)=>`<article class="ch1-scene"><div class="ch1-scene-figure" aria-hidden="true"><span class="ch1-figure-person">🧑🏽‍🎓</span><span class="ch1-figure-place">${x.art}</span><span class="ch1-figure-person">${i===1?'👩🏻‍🏫':'🧑🏻'}</span></div><div class="ch1-scene-content"><small>${e(x.tone)}</small><h6>${e(x.label)}</h6><div class="ch1-bubble" lang="de">${e(x.left)}</div><div class="ch1-bubble ch1-bubble-reply" lang="de">${e(x.right)}</div><div class="ch1-bubble" lang="de">${e(x.end)}</div><p>${e(x.tip)}</p><button type="button" data-speak="${e([x.left,x.right,x.end].join(' '))}" class="view-link">♫ Listen to the whole scene</button></div></article>`).join('')}</div></div>
<div class="ch1-lab-area"><div class="ch1-lab-heading"><h6>2 · Picture vocabulary</h6><p>Recognise familiar international words and practise their German articles.</p></div><div class="ch1-object-grid">${words.map(([word,full,en,icon])=>`<article class="ch1-object"><div class="ch1-object-art" aria-hidden="true">${icon}</div><strong lang="de">${e(full)}</strong><span>${e(en)}</span><button type="button" class="view-link" data-speak="${e(full)}">♫ Listen</button></article>`).join('')}</div></div>
<div class="ch1-lab-area"><div class="ch1-lab-heading"><h6>3 · Countries and languages</h6><p>Select a country to see how to describe where someone comes from and which language they speak.</p></div><div class="ch1-country-buttons" role="group" aria-label="Choose a country">${places.map((p,i)=>`<button type="button" data-ch1-country="${i}" aria-pressed="${i===0}" class="ch1-choice ${i===0?'active':''}">${e(p[0])}</button>`).join('')}</div><div class="ch1-country-result" aria-live="polite"><div class="ch1-globe" aria-hidden="true">🌍</div><div><strong id="ch1-place-de" lang="de">Ich komme aus Deutschland.</strong><p id="ch1-place-speech">Ich spreche Deutsch.</p><span id="ch1-place-gloss">I come from Germany. I speak German.</span><button type="button" id="ch1-place-listen" class="view-link" data-speak="Ich komme aus Deutschland. Ich spreche Deutsch.">♫ Listen</button></div></div></div>
<div class="ch1-lab-area"><div class="ch1-lab-heading"><h6>4 · Your first contact card</h6><p>Fill out a practice profile. It stays on this screen; it is not submitted to a teacher.</p></div><form class="ch1-profile" id="ch1-profile-form"><label>Vorname · First name<input name="first" maxlength="30" placeholder="Lina" autocomplete="off" /></label><label>Land · Country<input name="country" maxlength="40" placeholder="Deutschland" autocomplete="off" /></label><label>Wohnort · City<input name="city" maxlength="40" placeholder="Berlin" autocomplete="off" /></label><label>Sprache · Language<input name="language" maxlength="40" placeholder="Deutsch" autocomplete="off" /></label><button type="submit" class="btn btn-copper">Build my introduction</button><output id="ch1-profile-output" aria-live="polite">Complete the four fields and build your introduction.</output></form></div>
<div class="ch1-lab-area"><div class="ch1-lab-heading"><h6>5 · Recognise a spoken number</h6><p>Listen to a number between 1 and 20, then select the matching numeral.</p></div><div class="ch1-number-play"><button class="btn btn-outline" type="button" data-ch1-hear>♫ Hear the number</button><div class="ch1-number-answers" role="group" aria-label="Number choices"><button type="button" data-ch1-answer="4">4</button><button type="button" data-ch1-answer="12">12</button><button type="button" data-ch1-answer="17">17</button><button type="button" data-ch1-answer="20">20</button></div><p id="ch1-number-feedback" aria-live="polite">Choose the number you hear. Each new round has different choices.</p><button class="view-link" type="button" data-ch1-next>Another number →</button></div></div></section>`;
}
function init(root=document){if(!root.querySelector('.ch1-gallery'))return;let current=12;const arr=[4,12,17,20,8,16,19,3,11,15];let round=1;const strings=window.GERMAN_CHAPTER_ONE?.numbers||[];
const numbers=root.querySelector('.ch1-number-answers'),feedback=root.querySelector('#ch1-number-feedback');
function next(){current=arr[round++%arr.length];const opts=[current,...arr.filter(n=>n!==current).slice((round*3)%7,(round*3)%7+3)];while(opts.length<4)opts.push(arr[opts.length]);const unique=[...new Set(opts)];for(const n of arr)if(unique.length<4&&!unique.includes(n))unique.push(n);unique.sort((a,b)=>a-b);numbers.innerHTML=unique.map(n=>`<button type="button" data-ch1-answer="${n}">${n}</button>`).join('');feedback.textContent='Listen and select the number you hear.';}
function speak(t){if(!('speechSynthesis' in window))return;try{window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t);u.lang='de-DE';u.rate=.82;window.speechSynthesis.speak(u);}catch(_){}}
root.querySelectorAll('[data-ch1-country]').forEach(b=>b.addEventListener('click',()=>{const idx=Number(b.dataset.ch1Country),p=places[idx];root.querySelectorAll('[data-ch1-country]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});const from=p[2]==='CH'?'aus der Schweiz':'aus '+p[0],countryEnglish={DE:'Germany',AT:'Austria',CH:'Switzerland',FR:'France',ES:'Spain',IN:'India'}[p[2]];const a='Ich komme '+from+'.',s='Ich spreche '+p[1]+'.';root.querySelector('#ch1-place-de').textContent=a;root.querySelector('#ch1-place-speech').textContent=s;root.querySelector('#ch1-place-gloss').textContent='I come from '+countryEnglish+'. Languages: '+p[1]+'.';root.querySelector('#ch1-place-listen').dataset.speak=a+' '+s;}));
root.querySelector('#ch1-profile-form').addEventListener('submit',event=>{event.preventDefault();const fd=new FormData(event.currentTarget),values=['first','country','city','language'].map(k=>String(fd.get(k)||'').trim());const out=root.querySelector('#ch1-profile-output');if(values.some(v=>!v)){out.textContent='Please complete every field to build your introduction.';return;}out.textContent=`Hallo! Ich heiße ${values[0]}. Ich komme aus ${values[1]}. Ich wohne in ${values[2]}. Ich spreche ${values[3]}.`+' Check country articles with your teacher (for example: aus der Schweiz).';});
root.querySelector('[data-ch1-hear]').addEventListener('click',()=>speak(strings[current-1]||String(current)));
root.querySelector('[data-ch1-next]').addEventListener('click',next);
numbers.addEventListener('click',event=>{const b=event.target.closest('[data-ch1-answer]');if(!b)return;const ok=Number(b.dataset.ch1Answer)===current;feedback.textContent=ok?'Correct! '+current+' = '+strings[current-1]+'.':'Not quite. Listen again and try once more.';});
}
window.GERMAN_CH1_VISUAL_LAB={render,init};
})();